(5871071, 854323, 114238, '<td valign="top">I think this image has more to give, but I dotn think the software used to resize it has done a good god at all, it appears as if the colour channels arent aligned, like a 3D image with those glasses</td>', 'I think this image has more to give, but I dotn think the software used to resize it has done a good god at all, it appears as if the colour channels arent aligned, like a 3D image with those glasses', '2010-02-17 13:18:18.000000', NULL, 1),
(5871104, 854343, 46885, '<td valign="top">Wonderful snowflake. Such rare sight requires some careful work on contrast, I would crop tighter thus avoiding the white pool.</td>', 'Wonderful snowflake. Such rare sight requires some careful work on contrast, I would crop tighter thus avoiding the white pool.', '2010-02-17 13:59:47.000000', NULL, 1),
(5871108, 853998, 46885, '<td valign="top">Good, but the cutout effect on hands is a bit disconcerting. Would that be difficult to include wrists or sleeves?</td>', 'Good, but the cutout effect on hands is a bit disconcerting. Would that be difficult to include wrists or sleeves?', '2010-02-17 14:01:49.000000', NULL, 1),
