(5878013, 853474, 39427, '<td valign="top">I had an image just like this!  Yours is much better :P</td>', 'I had an image just like this!  Yours is much better :P', '2010-02-23 18:31:28.000000', NULL, 1),
(5878193, 854756, 65234, '<td valign="top">Gorgeous pastels and soft light.  Absolutely adore the egret; it just adds so much to the scene IMO.</td>', 'Gorgeous pastels and soft light.  Absolutely adore the egret; it just adds so much to the scene IMO.', '2010-02-23 21:16:46.000000', NULL, 1),
(5878197, 854342, 65234, '<td valign="top">Not generally a fan of centered composition but this works perfectly.  Bokeh is lovely, details are sharp and I can see just enough falling snow to make me realize the white in the background is wintry.  Bare branch is a clue, too ;-)  Really lovely bird shot.</td>', 'Not generally a fan of centered composition but this works perfectly.  Bokeh is lovely, details are sharp and I can see just enough falling snow to make me realize the white in the background is wintry.  Bare branch is a clue, too ;-)  Really lovely bird shot.', '2010-02-23 21:19:27.000000', NULL, 1),
(5878199, 854800, 65234, '<td valign="top">Beautiful scene and I just love the bird in the tree, maybe waiting for the fog to clear to start looking for food.</td>', 'Beautiful scene and I just love the bird in the tree, maybe waiting for the fog to clear to start looking for food.', '2010-02-23 21:20:19.000000', NULL, 1),
(5878200, 854599, 65234, '<td valign="top">Wonderfully sharp detail.</td>', 'Wonderfully sharp detail.', '2010-02-23 21:20:45.000000', NULL, 1),
(5878201, 854578, 65234, '<td valign="top">Very interesting scene, well captured.</td>', 'Very interesting scene, well captured.', '2010-02-23 21:21:08.000000', NULL, 1),
(5878202, 853583, 65234, '<td valign="top">Simple but effective.  Nice bokeh in the background and I love the little starbursts on some of the icicle''s highlights.</td>', 'Simple but effective.  Nice bokeh in the background and I love the little starbursts on some of the icicle''s highlights.', '2010-02-23 21:21:49.000000', NULL, 1),
(5878204, 853823, 65234, '<td valign="top">Beautiful little bird and nicely complementary background.</td>', 'Beautiful little bird and nicely complementary background.', '2010-02-23 21:22:23.000000', NULL, 1),
(5878205, 854034, 65234, '<td valign="top">Beautiful scene; horizon looks a little off-kilter to me but that could be an optical illusion.</td>', 'Beautiful scene; horizon looks a little off-kilter to me but that could be an optical illusion.', '2010-02-23 21:23:15.000000', NULL, 1),
(5878206, 854294, 65234, '<td valign="top">Like the light and deep darkness here.  Quite moody.</td>', 'Like the light and deep darkness here.  Quite moody.', '2010-02-23 21:23:37.000000', NULL, 1),
